window.kbPageData["views/entry/k-5f377175afc75157"] = {"key":"entry/k-5f377175afc75157","state":{"route":"entry/k-5f377175afc75157"},"node":{"id":"k-5f377175afc75157","mode":"k","title":"社会主义核心价值观","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["culture"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"5.社会主义核心价值观\n党的十八大提出，倡导富强、民主、文明、和谐，倡导自由、平等、公正、法治，倡导\n爱国、敬业、诚信、友善，积极培育和践行社会主义核心价值观。这与中国特色社会主义发\n展要求相契合，与中华优秀传统文化和人类文明优秀成果相承接，是我们党凝聚全党全社会\n价值共识作出的重要论断。富强、民主…","sources":[{"id":"266cb54b20bf6a24","label":"社会主义核心价值观","topic":"发展与治理","category":"非时政","text":"5.社会主义核心价值观\n党的十八大提出，倡导富强、民主、文明、和谐，倡导自由、平等、公正、法治，倡导\n爱国、敬业、诚信、友善，积极培育和践行社会主义核心价值观。这与中国特色社会主义发\n展要求相契合，与中华优秀传统文化和人类文明优秀成果相承接，是我们党凝聚全党全社会\n价值共识作出的重要论断。富强、民主、文明、和谐是国家层面的价值目标，自由、平等、\n公正、法治是社会层面的价值取向，爱国、敬业、诚信、友善是公民个人层面的价值准则，\n这 24 个字是社会主义核心价值观的基本内容，为培育和践行社会主义核心价值观提供了基\n本遵循。","source":{"doc":"6cbfb01fe723bba64b75","first":19,"last":19,"page":19,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"},{"id":"1aea66b8c06cac87","label":"社会主义核心价值观","topic":"发展与治理","category":"非时政","text":"1.社会主义核心价值观\n培育和践行社会主义核心价值观，是推进中国特色社会主义伟大事业、实现中华民族伟\n大复兴中国梦的战略任务。党的十八大提出，倡导富强、民主、文明、和谐，倡导自由、平\n等、公正、法治，倡导爱国、敬业、诚信、友善，积极培育和践行社会主义核心价值观。这\n与中国特色社会主义发展要求相契合，与中华优秀传统文化和人类文明优秀成果相承接，是\n我们党凝聚全党全社会价值共识作出的重要论断。富强、民主、文明、和谐是国家层面的价\n值目标，自由、平等、公正、法治是社会层面的价值取向，爱国、敬业、诚信、友善是公民\n个人层面的价值准则，这 24 个字是社会主义核心价值观的基本内容，为培育和践行社会主\n义核心价值观提供了基本遵循。\n——《关于培育和践行社会主义核心价值观的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":44,"last":44,"page":44,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"culture","title":"文化传承与创新表达"}],"units":{"k-5f377175afc75157":[]}};
